package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="succession_candidate_evidence") public class SuccessionCandidateEvidence extends RspAuditedEntity{public enum Visibility{CANDIDATE_VISIBLE,COMMITTEE_RESTRICTED}@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Column(nullable=false,length=200)private String title;@Column(name="original_filename",nullable=false,length=255)private String originalFilename;@Column(name="storage_provider",nullable=false,length=30)private String storageProvider;@Column(name="storage_object_key",nullable=false,unique=true,length=500)private String storageObjectKey;@Column(name="media_type",nullable=false,length=120)private String mediaType;@Column(name="byte_size",nullable=false)private long byteSize;@Column(nullable=false,length=64)private String checksum;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Visibility visibility;@Column(name="retention_tag",nullable=false,length=100)private String retentionTag;@Column(name="uploaded_by",nullable=false,length=100)private String uploadedBy;@Column(name="uploaded_at",nullable=false)private Instant uploadedAt;protected SuccessionCandidateEvidence(){}public SuccessionCandidateEvidence(String a,String candidate,String title,String filename,String provider,String key,String media,long size,String checksum,Visibility visibility,String retention,String actor,Instant at){super(a);candidateId=requiredText(candidate,"candidateId");this.title=requiredText(title,"title");originalFilename=requiredText(filename,"filename");storageProvider=requiredText(provider,"provider");storageObjectKey=requiredText(key,"key");mediaType=requiredText(media,"mediaType");if(size<1)throw new IllegalArgumentException("Evidence is empty");byteSize=size;this.checksum=requiredText(checksum,"checksum");if(this.checksum.length()!=64)throw new IllegalArgumentException("SHA-256 checksum is invalid");this.visibility=java.util.Objects.requireNonNull(visibility);retentionTag=requiredText(retention,"retentionTag");uploadedBy=requiredText(actor,"actor");uploadedAt=at;}public String getCandidateId(){return candidateId;}public String getTitle(){return title;}public String getOriginalFilename(){return originalFilename;}public String getStorageProvider(){return storageProvider;}public String getStorageObjectKey(){return storageObjectKey;}public String getMediaType(){return mediaType;}public long getByteSize(){return byteSize;}public String getChecksum(){return checksum;}public Visibility getVisibility(){return visibility;}public String getRetentionTag(){return retentionTag;}public String getUploadedBy(){return uploadedBy;}public Instant getUploadedAt(){return uploadedAt;}}
